  x.fillStyle="rgba(0,0,0,.35)";x.fillText("precisiondesign.club",c.width-12*k+1,c.height-12*k+1);x.fillStyle="rgba(255,255,255,.9)";x.fillText("precisiondesign.club",c.width-12*k,c.height-12*k);
